#include <set>
#include <iostream>

int main() {
    std::set<int> s = {10, 20};

    // 1. Successful insertion
    auto status1 = s.insert(30);
    if (status1.second) {
        std::cout << "Inserted: " << *status1.first << std::endl; 
    }

    // 2. Failed insertion (already exists)
    auto status2 = s.insert(20);
    if (!status2.second) {
        std::cout << "Already exists at: " << *status2.first << std::endl; 
    }

    return 0;
}
